//═════════════════════════════
// CAPACITOR — KEEP AWAKE
//═════════════════════════════
function keepAwakeOn() {
  try {
    if (window.Capacitor && Capacitor.Plugins && Capacitor.Plugins.KeepAwake) {
      Capacitor.Plugins.KeepAwake.keepAwake();
    }
  } catch(e) {}
}

function keepAwakeOff() {
  try {
    if (window.Capacitor && Capacitor.Plugins && Capacitor.Plugins.KeepAwake) {
      Capacitor.Plugins.KeepAwake.allowSleep();
    }
  } catch(e) {}
}

//═════════════════════════════
// VIBRATION SYSTEM (upgraded to Capacitor native haptics)
//═════════════════════════════
// Translate the game's [onMs, offMs, onMs, offMs, ...] patterns into Core
// Haptics events with a real relativeTime/duration/intensity/sharpness,
// instead of the fixed-length "impact" tap the fallback below has to fake
// a duration for. Same Heavy/Medium/Light duration thresholds as the
// fallback, so the two paths still feel like the same design language.
function buildHapticEvents(arr) {
  var events = [];
  var t = 0;
  for (var i = 0; i < arr.length; i += 2) {
    var durMs = arr[i];
    var gapMs = arr[i + 1] || 0;
    var intensity, sharpness;
    if (durMs >= 300) { intensity = 1.0; sharpness = 0.7; }
    else if (durMs >= 150) { intensity = 0.7; sharpness = 0.5; }
    else { intensity = 0.4; sharpness = 0.3; }
    events.push({ type: 'continuous', time: t / 1000, duration: Math.max(durMs / 1000, 0.01), intensity: intensity, sharpness: sharpness });
    t += durMs + gapMs;
  }
  return events;
}

function vibe(pattern) {
  if (!AUD.vibrationOn) return;
  // Core Haptics (iOS 13+, via our own CoreHapticsPlugin) — real per-pattern
  // duration/intensity/sharpness. Doesn't exist on Android, so this is a
  // natural no-op there and falls straight through to legacyVibe().
  if (window.Capacitor && Capacitor.Plugins && Capacitor.Plugins.CoreHaptics) {
    try {
      var events = buildHapticEvents(Array.isArray(pattern) ? pattern : [pattern]);
      Capacitor.Plugins.CoreHaptics.playPattern({ events: events }).catch(function() {
        legacyVibe(pattern);
      });
      return;
    } catch(e) {}
  }
  legacyVibe(pattern);
}

function legacyVibe(pattern) {
  // Try Capacitor native haptics first (real Android/iOS haptic engine)
  if (window.Capacitor && Capacitor.Plugins && Capacitor.Plugins.Haptics) {
    try {
      var arr = Array.isArray(pattern) ? pattern : [pattern];
      // Fire each "on" pulse as a separate impact (odd indexes are "on", even are "off" gaps)
      var delay = 0;
      for (var i = 0; i < arr.length; i += 2) {
        var duration = arr[i];
        (function(d, dur) {
          setTimeout(function() {
            try {
              // ImpactStyle enum values work on both iOS and Android
              var ImpactStyle = (Capacitor.Plugins.Haptics.ImpactStyle) ||
                { Heavy: 'HEAVY', Medium: 'MEDIUM', Light: 'LIGHT' };
              // impact() is a fixed-length native "tap" — it ignores dur
              // entirely, so every pulse in every pattern in the whole game
              // (a 100ms tap and a 500ms death buzz alike) physically felt
              // like the exact same brief click. That's the "tiny, not
              // sharp" feeling: fire it first for a crisp, percussive
              // onset, then immediately layer vibrate({duration}) on top
              // so the pulse actually lasts as long as its pattern says —
              // sharp attack, real felt presence behind it.
              if (dur >= 300) {
                Capacitor.Plugins.Haptics.impact({ style: ImpactStyle.Heavy || 'HEAVY' });
              } else if (dur >= 150) {
                Capacitor.Plugins.Haptics.impact({ style: ImpactStyle.Medium || 'MEDIUM' });
              } else {
                Capacitor.Plugins.Haptics.impact({ style: ImpactStyle.Light || 'LIGHT' });
              }
              Capacitor.Plugins.Haptics.vibrate({ duration: dur });
            } catch(e) {}
          }, d);
        })(delay, duration);
        // Add duration + gap for next pulse
        delay += duration + (arr[i + 1] || 0);
      }
      return;
    } catch(e) {}
  }
  // Fallback to web vibration API
  if (!navigator.vibrate) return;
  try { navigator.vibrate(pattern); } catch(e) {}
}

//═════════════════════════════
// CAPACITOR — LOCAL NOTIFICATIONS
//═════════════════════════════
var _notifScheduled = false;

async function requestNotificationPermission() {
  try {
    if (!window.Capacitor || !Capacitor.Plugins || !Capacitor.Plugins.LocalNotifications) return false;
    var perm = await Capacitor.Plugins.LocalNotifications.requestPermissions();
    return perm && perm.display === 'granted';
  } catch(e) { return false; }
}

// ── NOTIFICATION PREFERENCES ──
var _notifPrefs = null;

function getNotifPrefs() {
  if (_notifPrefs) return _notifPrefs;
  try {
    var raw = DDStore.getItem('dd_notif_prefs');
    _notifPrefs = raw ? JSON.parse(raw) : {};
  } catch(e) { _notifPrefs = {}; }
  // defaults — everything on except morning
  var defaults = { daily:1, streak:1, night:1, morning:0, void:1, comeback:1, events:1, ambush:1, friday13:1, xpweekend:1, voidweek:1, bloodmoon:1, architect:1 };
  for (var k in defaults) { if (_notifPrefs[k] === undefined) _notifPrefs[k] = defaults[k]; }
  return _notifPrefs;
}

function saveNotifPrefs() {
  try { DDStore.setItem('dd_notif_prefs', JSON.stringify(_notifPrefs)); } catch(e) {}
}

function toggleNotifPref(key, btn) {
  var prefs = getNotifPrefs();
  prefs[key] = prefs[key] ? 0 : 1;
  saveNotifPrefs();
  var on = !!prefs[key];
  btn.textContent = on ? 'On' : 'Off';
  btn.classList.toggle('on', on);
  btn.setAttribute('aria-pressed', String(on));
  say(key + ' notifications ' + (on ? 'enabled' : 'disabled') + '.');
}

function syncNotifToggleUI() {
  var prefs = getNotifPrefs();
  var map = { daily:'notif-toggle-daily', streak:'notif-toggle-streak', night:'notif-toggle-night',
              morning:'notif-toggle-morning', void:'notif-toggle-void', comeback:'notif-toggle-comeback',
              events:'notif-toggle-events', ambush:'notif-toggle-ambush', friday13:'notif-toggle-friday13',
              xpweekend:'notif-toggle-xpweekend', voidweek:'notif-toggle-voidweek',
              bloodmoon:'notif-toggle-bloodmoon', architect:'notif-toggle-architect' };
  for (var k in map) {
    var btn = document.getElementById(map[k]);
    if (!btn) continue;
    var on = !!prefs[k];
    btn.textContent = on ? 'On' : 'Off';
    btn.classList.toggle('on', on);
    btn.setAttribute('aria-pressed', String(on));
  }
}

async function rescheduleNotifications() {
  _notifScheduled = false;
  await scheduleAllNotifications();
  say('Notification preferences saved and applied.');
  setEvent('good', '🔔 Notification preferences saved.');
}

async function scheduleAllNotifications() {
  try {
    if (!window.Capacitor || !Capacitor.Plugins || !Capacitor.Plugins.LocalNotifications) return;
    var granted = await requestNotificationPermission();
    if (!granted) return;

    // Cancel all known notification IDs — empty array does nothing on iOS
    var knownIds = [];
    for (var _i = 1; _i <= 30; _i++) knownIds.push({ id: _i });
    try { await Capacitor.Plugins.LocalNotifications.cancel({ notifications: knownIds }); } catch(e) {}

    var now = new Date();
    var notifications = [];
    var id = 1;
    var prefs = getNotifPrefs();

    // ── DAILY DUNGEON — fires at 12:01 AM every day
    if (prefs.daily) notifications.push({
      id: id++,
      title: '📅 A New Dungeon Awaits',
      body: 'The dungeon has reset. A new challenge descends into the dark.',
      schedule: { on: { hour: 0, minute: 1 }, repeats: true },
      sound: 'sfx-unlock.wav', smallIcon: 'ic_launcher'
    });

    // ── DAILY STREAK REMINDER — fires at 7PM every day
    if (prefs.streak) notifications.push({
      id: id++,
      title: '🔥 Your Streak Is Waiting',
      body: 'Claim your daily descent before midnight or lose your streak.',
      schedule: { on: { hour: 19, minute: 0 }, repeats: true },
      sound: 'sfx-unlock.wav', smallIcon: 'ic_launcher'
    });

    // ── NIGHT MODE — fires at 8PM every day
    if (prefs.night) notifications.push({
      id: id++,
      title: '🌙 Night Mode Is Active',
      body: '+50% gold and cheaper shop prices. The dark rewards the bold.',
      schedule: { on: { hour: 20, minute: 0 }, repeats: true },
      sound: 'sfx-unlock.wav', smallIcon: 'ic_launcher'
    });

    // ── MORNING REMINDER — fires at 9AM every day
    if (prefs.morning) notifications.push({
      id: id++,
      title: '⚔ The Dungeon Awaits',
      body: 'A new day. New enemies. New loot. Descend.',
      schedule: { on: { hour: 9, minute: 0 }, repeats: true },
      sound: 'sfx-unlock.wav', smallIcon: 'ic_launcher'
    });

    // ── VOID REAPER WARNING — two hours before the awake Reaper's window closes.
    // (It fired 14 hours after you opened the app, whether the Reaper was awake or not.)
    var _vrs = (typeof _vrState !== 'undefined' && _vrState) ? _vrState : null;
    var voidTime = (_vrs && _vrs.awake && _vrs.awakenedAt && !_vrs.defeated)
      ? new Date(_vrs.awakenedAt + (VR_WINDOW_HOURS - 2) * 3600000) : null;
    if (voidTime && voidTime.getTime() <= now.getTime()) voidTime = null;
    if (prefs.void && voidTime) notifications.push({
      id: id++,
      title: '🌑 The Void Reaper Stirs',
      body: 'Two hours remain before the dungeon suffers. Defeat it or face consequences.',
      schedule: { at: voidTime },
      sound: 'sfx-unlock.wav', smallIcon: 'ic_launcher'
    });

    // ── COMEBACK — fires 48 hours after last open (one-time)
    var comeback = new Date(now.getTime() + (48 * 60 * 60 * 1000));
    if (prefs.comeback) notifications.push({
      id: id++,
      title: '⚔ The Dungeon Misses You',
      body: 'Your streak is at risk. The darkness grows without a hero.',
      schedule: { at: comeback },
      sound: 'sfx-unlock.wav', smallIcon: 'ic_launcher'
    });

    // ── SEASONAL EVENTS ──
    var year = now.getFullYear();

    // ── SEASONAL EVENTS wrapped in prefs.events
    // Halloween — October 25 at 9AM
    var halloween = new Date(year, 9, 25, 9, 0, 0);
    if (halloween <= now) halloween.setFullYear(year + 1);
    if (prefs.events) notifications.push({
      id: id++,
      title: '🎃 The Dungeon Grows Darker',
      body: 'Halloween has begun. Something ancient stirs in the crypt.',
      schedule: { at: halloween },
      sound: 'sfx-unlock.wav', smallIcon: 'ic_launcher'
    });

    // Christmas — December 20 at 9AM
    var christmas = new Date(year, 11, 20, 9, 0, 0);
    if (christmas <= now) christmas.setFullYear(year + 1);
    if (prefs.events) notifications.push({
      id: id++,
      title: '🎄 A Cursed Gift Awaits',
      body: 'Christmas descends on the dungeon. Festive enemies and rewards await.',
      schedule: { at: christmas },
      sound: 'sfx-unlock.wav', smallIcon: 'ic_launcher'
    });

    // Fourth of July — July 1 at 9AM
    var july4 = new Date(year, 6, 1, 9, 0, 0);
    if (july4 <= now) july4.setFullYear(year + 1);
    if (prefs.events) notifications.push({
      id: id++,
      title: '🎆 The Redcoats Invade',
      body: '76% bonus gold and XP all week. The Fourth of July event has begun.',
      schedule: { at: july4 },
      sound: 'sfx-unlock.wav', smallIcon: 'ic_launcher'
    });

    // Cinco de Mayo — May 5 at 9AM
    var cinco = new Date(year, 4, 5, 9, 0, 0);
    if (cinco <= now) cinco.setFullYear(year + 1);
    if (prefs.events) notifications.push({
      id: id++,
      title: '🌮 El Taco Blade Awaits',
      body: 'Cinco de Mayo is here. One day only — +50% XP and the El Taco Blade in the Blacksmith.',
      schedule: { at: cinco },
      sound: 'sfx-unlock.wav', smallIcon: 'ic_launcher'
    });

    // Brazil Independence Day — September 7 at 9AM
    var brazil = new Date(year, 8, 7, 9, 0, 0);
    if (brazil <= now) brazil.setFullYear(year + 1);
    if (prefs.events) notifications.push({
      id: id++,
      title: '🇧🇷 Brasil Independente',
      body: 'Brazil Independence Day. The dungeon flies the green and gold. Bonus gold and XP today.',
      schedule: { at: brazil },
      sound: 'sfx-unlock.wav', smallIcon: 'ic_launcher'
    });

    // Valentine's Day — February 13 at 9AM
    var valentines = new Date(year, 1, 13, 9, 0, 0);
    if (valentines <= now) valentines.setFullYear(year + 1);
    if (prefs.events) notifications.push({
      id: id++,
      title: '💘 The Heartbreaker Stirs',
      body: "Valentine's Day event. Love is a curse. The Heartbreaker enemy has entered the dungeon.",
      schedule: { at: valentines },
      sound: 'sfx-unlock.wav', smallIcon: 'ic_launcher'
    });

    // St. Patrick's Day — March 14 at 9AM
    var stpatricks = new Date(year, 2, 14, 9, 0, 0);
    if (stpatricks <= now) stpatricks.setFullYear(year + 1);
    if (prefs.events) notifications.push({
      id: id++,
      title: "☘ The Luck o' the Dungeon",
      body: "St. Patrick's Day. Extra gold drops and Lucky Potion available in the shop.",
      schedule: { at: stpatricks },
      sound: 'sfx-unlock.wav', smallIcon: 'ic_launcher'
    });

    // Leo's Birthday — March 23 at 9AM (in-game birthday event)
    var birthday = new Date(year, 2, 23, 9, 0, 0);
    if (birthday <= now) birthday.setFullYear(year + 1);
    if (prefs.events) notifications.push({
      id: id++,
      title: '🎂 The Dungeon Celebrates',
      body: "It's the creator's birthday. A special gift awaits in the dungeon today.",
      schedule: { at: birthday },
      sound: 'sfx-unlock.wav', smallIcon: 'ic_launcher'
    });

    // Ambush Days — January, April, July, October 15th at 8AM
    var ambushMonths = [0, 3, 6, 9]; // Jan, Apr, Jul, Oct
    if (prefs.ambush) ambushMonths.forEach(function(month) {
      var ambush = new Date(year, month, 15, 8, 0, 0);
      if (ambush <= now) ambush.setFullYear(year + 1);
      notifications.push({
        id: id++,
        title: '⚔ Ambush Day Has Begun',
        body: 'Every battle today is a multi-enemy ambush. Enter at your own risk.',
        schedule: { at: ambush },
        sound: 'sfx-unlock.wav', smallIcon: 'ic_launcher'
      });
    });

    // Friday the 13th — dynamic, find next one
    (function() {
      var d = new Date(now);
      d.setDate(d.getDate() + 1); // start from tomorrow
      for (var i = 0; i < 400; i++) { // scan up to ~13 months ahead
        if (d.getDay() === 5 && d.getDate() === 13) {
          var fri13 = new Date(d.getFullYear(), d.getMonth(), 13, 8, 0, 0);
          if (!prefs.friday13) break; // (it was scheduled even with its switch off)
          notifications.push({
            id: id++,
            title: '💀 Friday the 13th',
            body: 'Cursed enemies have entered the dungeon. Danger and rare loot await.',
            schedule: { at: fri13 },
            sound: 'sfx-unlock.wav', smallIcon: 'ic_launcher'
          });
          break;
        }
        d.setDate(d.getDate() + 1);
      }
    })();

    // ── WEEKLY EVENTS ──

    // XP Weekend — every Saturday at 8AM
    if (prefs.xpweekend) notifications.push({
      id: id++,
      title: '⚡ XP Weekend Has Begun',
      body: 'Double XP all weekend. The best time to level up your characters.',
      schedule: { on: { weekday: 7, hour: 8, minute: 0 }, repeats: true },
      sound: 'sfx-unlock.wav', smallIcon: 'ic_launcher'
    });

    // Void Week — every Monday at 8AM
    if (prefs.voidweek) notifications.push({
      id: id++,
      title: '🌑 Void Week Descends',
      body: 'Double gold this week. But enemies are stronger. Enter at your own risk.',
      schedule: { on: { weekday: 2, hour: 8, minute: 0 }, repeats: true },
      sound: 'sfx-unlock.wav', smallIcon: 'ic_launcher'
    });

    // Blood Moon — 1st of every month at 8AM
    if (prefs.bloodmoon) notifications.push({
      id: id++,
      title: '🔴 The Blood Moon Rises',
      body: 'Enemies hit harder this week but gold flows freely. High risk, high reward.',
      schedule: { on: { day: 1, hour: 8, minute: 0 }, repeats: true },
      sound: 'sfx-unlock.wav', smallIcon: 'ic_launcher'
    });

    // Architect Week — 8th of every month at 8AM
    if (prefs.architect) notifications.push({
      id: id++,
      title: '🏛 Architect Week Begins',
      body: 'Bonus XP this week and unique encounters with The Architect.',
      schedule: { on: { day: 8, hour: 8, minute: 0 }, repeats: true },
      sound: 'sfx-unlock.wav', smallIcon: 'ic_launcher'
    });

    await Capacitor.Plugins.LocalNotifications.schedule({ notifications: notifications });
    _notifScheduled = true;
    console.log('[DD] Notifications scheduled: ' + notifications.length);
  } catch(e) {
    console.warn('[DD] Notification scheduling failed:', e);
  }
}

