// ANDROID BACK BUTTON HANDLER
//═════════════════════════════
function initBackButton() {
  try {
    if (!window.Capacitor || !Capacitor.Plugins || !Capacitor.Plugins.App) return;
    Capacitor.Plugins.App.addListener('backButton', function() {
      // If any overlay or settings panel is open — close it first
      var openPanel = document.querySelector('.settings-panel.active');
      if (openPanel) { openPanel.classList.remove('active'); say('Closed.'); return; }

      var openOverlay = document.querySelector('.overlay-panel[style*="flex"], .overlay[style*="flex"]');
      if (openOverlay) { openOverlay.style.display = 'none'; say('Closed.'); return; }

      // Handle by current screen
      switch (_currentScreen) {
        case 'menu':
          // On main menu — ask if they want to exit
          showChoiceModal(
            'Exit Dungeon Descent?',
            'Your progress is saved.',
            [
              { label: 'Exit', action: function() { Capacitor.Plugins.App.exitApp(); } },
              { label: 'Stay', action: function() {} }
            ]
          );
          break;
        case 'dungeon':
          // In dungeon — open pause menu instead of exiting
          if (typeof openPauseMenu === 'function') {
            openPauseMenu();
            say('Paused. Press back again or use the menu to continue or exit.');
          }
          break;
        case 'settings':
        case 'charlist':
        case 'bestiary':
        case 'deathlog':
        case 'graveyard':
        case 'challenges':
        case 'coinshop':
        case 'obituary':
        case 'library':
        case 'void-reaper':
        case 'raid':
        case 'blacksmith':
        case 'runsummary':
          // On any sub-screen — go back to menu
          goTo('menu');
          say('Back to main menu.');
          break;
        case 'create':
          // In character creation — go back to character list
          goTo('charlist');
          say('Back to character selection.');
          break;
        default:
          goTo('menu');
          break;
      }
    });
    console.log('[DD] Back button handler initialized');
  } catch(e) {
    console.warn('[DD] Back button init failed:', e);
  }
}
var _shakeEnabled = false; // default off — enabled by user gesture (required for iOS permission)
var _lastShakeTime = 0;
var _shakeThreshold = 15; // sensitivity
var _shakeCooldown = 800; // ms between shakes

var _shakeListenerAttached = false;
function initShakeToAttack() {
  if (_shakeListenerAttached) return;
  try {
    // @capacitor/motion has no native iOS/Android code at all (no podspec,
    // no ios/ or android/ folder) — it's a pure wrapper around the browser's
    // own DeviceMotionEvent, and only registers as Capacitor.Plugins.Motion
    // if its JS file is explicitly loaded into the page, which it never was
    // here (only capacitor.js itself is loaded). So that check always failed
    // and this never ran, on iOS, Android, OR in a browser — the native app
    // runs this same web content inside a WKWebView, which supports
    // DeviceMotionEvent natively same as Safari, so talking to it directly
    // works identically in both places without needing the plugin at all.
    if (typeof window.DeviceMotionEvent === 'undefined') return; // no accelerometer support here at all

    function _attachMotionListener() {
      if (_shakeListenerAttached) return;
      _shakeListenerAttached = true;
      window.addEventListener('devicemotion', function(event) {
        if (!_shakeEnabled) return;
        if (!DS || !DS.inCombat) return;
        var a = event.acceleration || event.accelerationIncludingGravity;
        if (!a) return;
        var x = a.x || 0, y = a.y || 0, z = a.z || 0;
        // If using gravity-included, subtract ~9.8 from z to get net acceleration
        if (!event.acceleration && event.accelerationIncludingGravity) z = z - 9.8;
        var force = Math.sqrt(x * x + y * y + z * z);
        var now = Date.now();
        if (force > _shakeThreshold && now - _lastShakeTime > _shakeCooldown) {
          _lastShakeTime = now;
          if (force > 25 && DS.sp >= 3) {
            // ("skill0" isn't an action the fight handles, so a hard shake wasted your turn)
            var _shSkills = getUnlockedSkills();
            var _shIdx = _shSkills.findIndex(function(s){ return DS.sp >= s.spCost; });
            if (_shIdx >= 0) { say('Shake attack! Unleashing ' + _shSkills[_shIdx].name + '!'); useSkill(_shIdx); }
            else doFight('attack');
          } else {
            doFight('attack');
          }
        }
      });
      console.log('[DD] Shake to attack enabled');
    }

    // iOS 13+ (Safari and WKWebView alike) requires explicit permission for DeviceMotion
    if (typeof DeviceMotionEvent.requestPermission === 'function') {
      DeviceMotionEvent.requestPermission().then(function(state) {
        if (state === 'granted') {
          _attachMotionListener();
        } else {
          console.warn('[DD] DeviceMotion permission denied');
        }
      }).catch(function(e) {
        console.warn('[DD] DeviceMotion permission error:', e);
      });
    } else {
      // Android or older iOS — no permission needed
      _attachMotionListener();
    }
  } catch(e) {
    console.warn('[DD] Motion init failed:', e);
  }
}

function toggleShakeAttack() {
  _shakeEnabled = !_shakeEnabled;
  DDStore.setItem('dd_shake', _shakeEnabled ? '1' : '0');

  // Sync toggle button UI
  var btn = document.getElementById('shake-toggle');
  if (btn) {
    btn.textContent = _shakeEnabled ? 'On' : 'Off';
    btn.classList.toggle('on', _shakeEnabled);
    btn.setAttribute('aria-pressed', String(_shakeEnabled));
  }

  if (_shakeEnabled) {
    // iOS 13+ permission MUST come from a direct user gesture — this click IS one
    var isIOS = /iPad|iPhone|iPod/.test(navigator.userAgent) && !window.MSStream;
    if (isIOS && typeof DeviceMotionEvent !== 'undefined' && typeof DeviceMotionEvent.requestPermission === 'function') {
      DeviceMotionEvent.requestPermission().then(function(state) {
        if (state === 'granted') {
          _shakeListenerAttached = false;
          initShakeToAttack();
          say('Shake to attack enabled. Motion permission granted.');
        } else {
          _shakeEnabled = false;
          DDStore.setItem('dd_shake', '0');
          if (btn) { btn.textContent = 'Off'; btn.classList.remove('on'); btn.setAttribute('aria-pressed', 'false'); }
          say('Motion permission denied. Shake to attack unavailable.');
        }
      }).catch(function() {
        _shakeListenerAttached = false;
        initShakeToAttack();
        say('Shake to attack enabled.');
      });
    } else {
      // Android or older iOS — no permission dialog needed
      _shakeListenerAttached = false;
      initShakeToAttack();
      say('Shake to attack enabled.');
    }
  } else {
    say('Shake to attack disabled.');
  }
}

