var _screenReaderActive = false;
var _screenReaderInitDone = false;

async function initScreenReader() {
  if (_screenReaderInitDone) return;
  _screenReaderInitDone = true;
  try {
    if (!window.Capacitor || !Capacitor.Plugins || !Capacitor.Plugins.ScreenReader) return;

    // Check current state
    var result = await Capacitor.Plugins.ScreenReader.isEnabled();
    _screenReaderActive = !!(result && result.value);
    _onScreenReaderStateChange(_screenReaderActive);

    // Listen for changes (user turns VoiceOver on/off mid-session)
    Capacitor.Plugins.ScreenReader.addListener('stateChange', function(state) {
      _screenReaderActive = !!(state && state.value);
      _onScreenReaderStateChange(_screenReaderActive);
      console.log('[DD] Screen reader ' + (_screenReaderActive ? 'enabled' : 'disabled'));
    });

    console.log('[DD] Screen reader detected: ' + _screenReaderActive);
  } catch(e) {
    console.warn('[DD] ScreenReader init failed:', e);
  }
}

function _onScreenReaderStateChange(active) {
  // When VoiceOver turns on — make sure aria-live region is ready
  // and announce current screen to orient the user
  if (active) {
    // Ensure announce element exists and is properly set up
    var el = document.getElementById('aria-announce');
    if (el) {
      el.setAttribute('aria-live', 'assertive');
      el.setAttribute('aria-atomic', 'true');
    }
    // Announce the current screen
    setTimeout(function() {
      var current = document.querySelector('.screen.active');
      if (current) {
        var label = current.getAttribute('aria-label') || 'Dungeon Descent';
        say('Screen reader active. ' + label + '.');
      }
    }, 500);
  }
}

