// The store is Android's Google Play or iOS's App Store, whichever this device is actually running.
function getIAPPlatform() {
  if (!window.CdvPurchase) return null;
  var isIOSDevice = window.Capacitor && typeof Capacitor.getPlatform === 'function' && Capacitor.getPlatform() === 'ios';
  return isIOSDevice ? CdvPurchase.Platform.APPLE_APPSTORE : CdvPurchase.Platform.GOOGLE_PLAY;
}

function initIAP() {
  try {
    if (!window.CdvPurchase) {
      console.warn('[DD] CdvPurchase not available');
      return;
    }
    var store = CdvPurchase.store;
    var ProductType = CdvPurchase.ProductType;
    var Platform = getIAPPlatform();

    // Register all three products
    store.register(IAP_PRODUCTS.map(function(p) {
      return {
        id: p.id,
        type: ProductType.CONSUMABLE,
        platform: Platform
      };
    }));

    // When a purchase is approved — finish it and award coins
    store.when()
      .approved(function(transaction) {
        // Award coins immediately on approval — no server validator needed
        try {
          // Get product ID from transaction
          var productId = null;
          if (transaction.products && transaction.products.length > 0) {
            productId = transaction.products[0].id;
          } else if (transaction.productId) {
            productId = transaction.productId;
          }
          console.log('[DD] Purchase approved, productId:', productId);
          var product = IAP_PRODUCTS.find(function(p){ return p.id === productId; });
          if (product) {
            // Check quantity in case player bought multiple
            var qty = 1;
            try { qty = transaction.products[0].quantity || 1; } catch(e) {}
            var coinsToAward = product.coins * qty;
            var rs = getRaidSave();
            rs.mysteryCoins = (rs.mysteryCoins || 0) + coinsToAward;
            setRaidSave(rs);
            sfx('sfx-unlock');
            vibe(VIBE.achievement);
            say('Purchase successful! ' + coinsToAward + ' Mystery Coins added. Thank you for supporting Dungeon Descent!');
            addLog('🪙 ' + product.label + ' x' + qty + ' — ' + coinsToAward + ' Mystery Coins added!');
            if (document.getElementById('screen-coinshop') &&
                document.getElementById('screen-coinshop').classList.contains('active')) {
              renderCoinShop();
            }
          }
        } catch(e) { console.warn('[DD] Coin award error:', e); }
        // Finish the transaction
        transaction.finish();
      })
      .productUpdated(function(product) {
        _iapProducts[product.id] = product;
      });

    // Handle store errors
    store.error(function(error) {
      if (error.code === CdvPurchase.ErrorCode.PAYMENT_CANCELLED) return; // user cancelled — no message needed
      console.warn('[DD] Store error:', error.code, error.message);
      say('Purchase error: ' + (error.message || 'Something went wrong. Please try again.'));
    });

    // Initialize the store
    store.initialize([Platform]);
    store.ready(function() {
      _iapReady = true;
      console.log('[DD] IAP ready');
    });

  } catch(e) {
    console.warn('[DD] IAP init failed:', e);
  }
}

function buyCoins(productId) {
  try {
    if (!_isOnline) { say('No internet connection. Purchases require internet.'); return; }
    if (!window.CdvPurchase) {
      say('Purchases are not available on this device.');
      return;
    }
    if (!_iapReady) {
      say('Store is still loading. Please wait a few seconds and try again.');
      // Try to reinitialize
      setTimeout(function(){ initIAP(); }, 1000);
      return;
    }
    var store = CdvPurchase.store;
    var product = store.get(productId, getIAPPlatform());
    if (!product) {
      say('Product not available. Please try again.');
      return;
    }
    var offer = product.getOffer();
    if (!offer) {
      say('No offer available for this product.');
      return;
    }
    store.order(offer);
  } catch(e) {
    console.warn('[DD] Purchase failed:', e);
    say('Purchase failed. Please try again.');
  }
}
