async function showRewardedAd() {
  try {
    if (!_isOnline) { say('No internet connection. Ads require internet.'); return; }
    if (_adCooldown) { say('Please wait before watching another ad.'); return; }
    if (!_adLoaded) {
      say('No ad available right now. Try again in a moment.');
      loadRewardedAd();
      return;
    }
    if (!window.Capacitor || !Capacitor.Plugins || !Capacitor.Plugins.AdMob) {
      say('Ads are only available on the Android app.');
      return;
    }
    var result = await Capacitor.Plugins.AdMob.showRewardVideoAd();
    if (result && result.type === 'Rewarded') {
      // Award 10 Mystery Coins
      var rs = getRaidSave();
      rs.mysteryCoins = (rs.mysteryCoins || 0) + 10;
      setRaidSave(rs);
      addLog('🎬 Ad watched — +10 Mystery Coins awarded!');
      say('Thank you for watching! 10 Mystery Coins added to your account.');
      vibe(VIBE.achievement);
      // Update coin display if on coin shop
      if (document.getElementById('screen-coinshop') && 
          document.getElementById('screen-coinshop').classList.contains('active')) {
        renderCoinShop();
      }
      // Cooldown 5 minutes between ads
      _adCooldown = true;
      _adLoaded = false;
      setTimeout(function() { 
        _adCooldown = false; 
        loadRewardedAd();
      }, 5 * 60 * 1000);
    }
  } catch(e) {
    console.warn('[DD] Ad show failed:', e);
    say('Ad not available right now. Try again later.');
    loadRewardedAd();
  }
}
