var _GUN_AUDIO = { charge: 'data:audio/mp3;base64,', shot: 'data:audio/mp3;base64,' };
var _HUNTER_AUDIO = {
  heartbeat: _audioUrl('hunter-heartbeat.mp3'),
  jumpscare: _audioUrl('hunter-jumpscare.mp3'),
  music:     _audioUrl('hunter-music.mp3')
};
var _hunterMusicEl = null;
var _heartbeatEl = null;
var _heartbeatInterval = null;
var _heartbeatPanner = null;
// Low-HP heartbeat tier — 0 normal, 1 warning (<=10%), 2 critical (<=5%).
// Tracked separately from _heartbeatInterval so the warning->critical
// transition can restart the loop at a faster, more urgent rate instead
// of just leaving the same 800ms warning beat running all the way to 0 HP.
var _hpWarnTier = 0;
// Add hunter-theme to TRACK_FILES now that _HUNTER_AUDIO is defined
try { if (typeof TRACK_FILES !== 'undefined') TRACK_FILES['hunter-theme'] = _HUNTER_AUDIO.music; } catch(e) {}

function initHunterAudio() {
  // Heartbeat element — short SFX, plain Audio is fine
  if (!_heartbeatEl) {
    _heartbeatEl = new Audio(_HUNTER_AUDIO.heartbeat);
    _heartbeatEl.loop = false;
    _heartbeatEl.volume = AUD ? (AUD.sfxVol || 0.8) : 0.8;
    // Route through Web Audio so the loop can be panned live to whichever
    // direction the hunter is coming from — updated on every beat in
    // playHeartbeat() below, so it tracks your last move in real time.
    try {
      if (window.AUD && AUD.ctx && AUD.ctx.createMediaElementSource) {
        var src = AUD.ctx.createMediaElementSource(_heartbeatEl);
        _heartbeatPanner = AUD.ctx.createStereoPanner();
        src.connect(_heartbeatPanner);
        _heartbeatPanner.connect(AUD.ctx.destination);
      }
    } catch (e) { _heartbeatPanner = null; }
  }
}

function playHunterMusic() {
  if (!AUD || !AUD.musicOn) return;
  initHunterAudio();
  // Pause current dungeon music
  try {
    Object.values(AUD.tracks || {}).forEach(function(t) {
      if (t && !t.paused) { t._wasPlayingBeforeHunter = true; t.pause(); }
    });
    if (AUD.currentSource) { try { AUD.currentSource.stop(); } catch(e) {} AUD.currentSource = null; }
    if (_howlMusic) { try { _howlMusic.stop(); } catch(e) {} }
  } catch(e) {}
  // Use Web Audio GainNode path if available (iOS volume control)
  if (_webAudioReady && AUD.ctx && AUD.musicGain) {
    loadAudioBuffer(_HUNTER_AUDIO.music, AUD.buffers, 'hunter-theme', function(buffer) {
      if (!buffer) {
        // Fallback to Audio element
        if (!_hunterMusicEl) { _hunterMusicEl = new Audio(_HUNTER_AUDIO.music); _hunterMusicEl.loop = true; }
        _hunterMusicEl.volume = AUD.musicVol || 0.7;
        _hunterMusicEl.currentTime = 0;
        _hunterMusicEl.play().catch(function(){});
        return;
      }
      AUD.musicGain.gain.setValueAtTime(AUD.musicVol, AUD.ctx.currentTime);
      AUD.currentSource = playBuffer(buffer, AUD.musicGain, true);
    });
  } else {
    if (!_hunterMusicEl) { _hunterMusicEl = new Audio(_HUNTER_AUDIO.music); _hunterMusicEl.loop = true; }
    _hunterMusicEl.volume = AUD.musicVol || 0.7;
    _hunterMusicEl.currentTime = 0;
    _hunterMusicEl.play().catch(function(){});
  }
}

function stopHunterMusic() {
  if (_hunterMusicEl) {
    _hunterMusicEl.pause();
    _hunterMusicEl.currentTime = 0;
  }
  // Resume dungeon music via playTrack — same pattern used everywhere else
  if (AUD && AUD.musicOn) {
    try { playTrack(exploTrackForFloor(DS.floor)); } catch(e) {}
  }
}

function playHunterJumpScare() {
  if (!AUD || !AUD.sfxOn) return;
  initHunterAudio();
  var jsAudio = new Audio(_HUNTER_AUDIO.jumpscare);
  jsAudio.volume = AUD.sfxVol || 0.9;
  jsAudio.play().catch(function(){});
}

function playHeartbeat() {
  if (!AUD || !AUD.sfxOn) return;
  initHunterAudio();
  _heartbeatEl.volume = AUD.sfxVol || 0.8;
  if (_heartbeatPanner) {
    var dirCue = _hunterDirCue();
    _heartbeatPanner.pan.value = dirCue ? dirCue.pan : 0;
  }
  _heartbeatEl.currentTime = 0;
  _heartbeatEl.play().catch(function(){});
}

function startHeartbeatLoop(intervalMs) {
  stopHeartbeatLoop();
  playHeartbeat();
  _heartbeatInterval = setInterval(function() {
    playHeartbeat();
  }, intervalMs);
}

function stopHeartbeatLoop() {
  if (_heartbeatInterval) { clearInterval(_heartbeatInterval); _heartbeatInterval = null; }
  if (_heartbeatEl) { _heartbeatEl.pause(); _heartbeatEl.currentTime = 0; }
}

