function companionSay(msg, duration) {
  // Respect guide toggle
  if (typeof DS !== 'undefined' && DS.guideEnabled === false) return;
  // Show companion speech bubble
  var bubble = document.getElementById('companion-bubble');
  var nameEl = document.getElementById('companion-name-label');
  var textEl = document.getElementById('companion-text');
  var img = document.getElementById('companion-img');
  if (!bubble || !textEl) return;
  if (nameEl) nameEl.textContent = getCompanionName();
  textEl.textContent = msg;
  if (img) img.src = _COMPANION_IMG;
  bubble.style.display = 'flex';
  bubble.style.animation = 'companionFadeIn 0.4s ease';
  say(getCompanionName() + ' says — ' + msg);
  // Auto hide after duration
  clearTimeout(bubble._hideTimer);
  bubble._hideTimer = setTimeout(function() {
    bubble.style.animation = 'companionFadeOut 0.3s ease forwards';
    setTimeout(function() { bubble.style.display = 'none'; }, 300);
  }, duration || 4000);
}

