function getGuideDialogue(event) {
  var personality = (typeof DS !== 'undefined' && DS.guidePersonality) || 'encouraging';
  var lines = GUIDE_DIALOGUE[personality] && GUIDE_DIALOGUE[personality][event];
  if (!lines || !lines.length) return null;
  var line = lines[Math.floor(Math.random() * lines.length)];
  // Replace {lvl} placeholder
  if (typeof DS !== 'undefined') line = line.replace('{lvl}', DS.level || 1);
  return line;
}
