var VOID_STORY = [
  ['Fragment I — The Bones', 'She was arranging bones when you first saw her. Not randomly. A pattern. Something geometric, something that should not be possible for a child to know. She looked up when you entered. She was not surprised.'],
  ['Fragment II — The Eyes', 'Her eyes are wrong. Not the color — the depth. When she looks at you there is something behind the looking. Like she is cataloguing. Like she has seen a thousand versions of this moment and is checking which one this is.'],
  ['Fragment III — The Question', 'She asked you something the second time you met. Not your name. Not where you came from. She asked how many times you had died. You told her. She nodded like she already knew. Like she was confirming.'],
  ['Fragment IV — The Wall', 'She walks through walls. Not metaphorically. Literally. The stone parts for her like water. She does not notice it happening. To her it is normal. The dungeon does not stop her. The dungeon does not stop her from anything.'],
  ['Fragment V — The Count', 'She knows how many people have died in this dungeon. The exact number. She said it once, quietly, while you were watching her sort her bones. The number was very large. She said it the way you would say the weather.'],
  ['Fragment VI — The Age', 'She is not a child. This much becomes clear the more time you spend near her. The face is young. The voice is young. But the weight behind the voice is not. Something very old is wearing something very small.'],
  ['Fragment VII — The Dungeon', 'The dungeon responds to her. Subtly. Doors that should be locked are not. Enemies that should notice her do not. The dungeon treats her less like an inhabitant and more like a part of itself. Like an organ. Like a heartbeat.'],
  ['Fragment VIII — The Name', 'You asked her name. She thought about it for a long time. Not because she forgot — because she was deciding which one to give you. She has had many. The one she gave you felt like a gift. It felt like a secret. Keep it.'],
  ['Fragment IX — The Before', 'She was here before the dungeons had names. Before the floors were numbered. Before anyone thought to come looking for treasure or glory or redemption. She was here then. Arranging bones. Waiting for something.'],
  ['Fragment X — The Fragments', 'She gives you pieces of herself. Literally — the items she presses into your hand carry something of her. Memory, maybe. Or intention. Each one changes you slightly in ways you cannot name. You feel older after each meeting.'],
  ['Fragment XI — The Others', 'You are not the first she has followed. There were others before you — she shows you, briefly, a list of names on a piece of something that is not paper. Most of the names you do not recognize. One of them is Julio.'],
  ['Fragment XII — The Purpose', 'She has a purpose. She will not tell you what it is directly but you piece it together from the fragments. She is collecting something. Not items. Not gold. She is collecting endings. Every death in the dungeon she witnesses and keeps.'],
  ['Fragment XIII — The Void', 'She told you about the void once. Not Void Mode — the actual void. The thing underneath the dungeon. The reason the dungeon exists. She described it the way you would describe a childhood home. Familiar. Comfortable. Hers.'],
  ['Fragment XIV — The Hunger', 'The dungeon is hungry. She said this matter-of-factly. It always has been. It feeds on endings — on the deaths that happen here, on the stories that stop mid-sentence on floor seven. She is its appetite made visible. Its need given a face.'],
  ['Fragment XV — The Protection', 'She protects you, in her way. Not by fighting — she has never once raised a hand against anything. But things that should have killed you do not. Coincidences that favor your survival. She is arranging outcomes like she arranges bones.'],
  ['Fragment XVI — The Memory', 'She remembers every adventurer who ever entered this dungeon. Every one. Their faces, their choices, their final moments. She carries all of them. You wonder if she gets heavy. You wonder if that is what the weight in her eyes is.'],
  ['Fragment XVII — The Truth', "The truth is simple once you see it. She is not a child who wandered into a dungeon. She is the dungeon's memory. Its witness. The part of it that watches and records and never forgets. She is what the dungeon uses to mourn."],
  ['Fragment XVIII — The Offer', 'She offered you something once. She said she could show you your own ending — not now, but the shape of it. How it would feel. You said no. She nodded like that was the right answer. Like that was the one she was hoping for.'],
  ['Fragment XIX — The Bones Again', 'The bones she arranges are not random animal remains. You realize this late. The patterns she makes are maps. Maps of the dungeon as it was, as it is, as it will be. She updates them after every death. The dungeon changes when people die in it.'],
  ['Fragment XX — The Loneliness', 'She is alone in the way that only something immortal can be alone. Everyone who comes through eventually leaves or dies. She stays. She has always stayed. You are the first person in a very long time to ask her how she was doing.'],
  ['Fragment XXI — The Crack', 'There is a crack in the dungeon deepest floor. She showed you once, briefly. Through the crack you could see the void she described — endless, dark, patient. She said the crack has been getting larger. Slowly. Over centuries. But larger.'],
  ['Fragment XXII — The Fear', 'She is afraid of something. You did not think she could be afraid of anything. But when the crack in the deepest floor came up she went quiet in a different way. A smaller way. A way that reminded you she is wearing a child face for a reason.'],
  ['Fragment XXIII — The Ask', 'She asked you to do something. She would not say what — only that when the time came you would know, and that you would have to choose quickly, and that you should choose to close it rather than enter it. She did not explain what it was.'],
  ['Fragment XXIV — The Gift', 'The last fragment she gave you felt different. Heavier. She held it longer before passing it over. She said — This one has my name in it. The real one. Not the one I gave you. You could feel it humming. You did not look.'],
  ['Fragment XXV — What She Was', 'She was the dungeon conscience. The part of it that remembers every person it has ever consumed and carries them gently. She was never lost. She was placed here. By something that needed a witness. Something that could not watch itself. The crack is getting larger. She asked you to remember her name. You will.'],
];

function getVoidFragments() {
  return parseInt(DDStore.getItem('dd_void_fragments') || '0');
}

function addVoidFragment() {
  var current = getVoidFragments();
  if (current >= 25) return; // already complete
  var next = current + 1;
  DDStore.setItem('dd_void_fragments', next);

  // Get story chapter for this fragment
  var chapter = VOID_STORY[current];
  if (!chapter) return;

  // Add to Chronicles library
  addVoidChapterToLibrary(next, chapter[0], chapter[1]);

  // Announce
  var msg = 'Void Fragment ' + next + ' of 25 received. A new chapter has been added to the Void Chronicles. Find it in your library.';
  addLog('👁️ ' + msg);
  say(msg);

  // Add as permanent inventory item
  var fragItem = {
    name: 'Void Fragment ' + next,
    icon: '👁️',
    type: 'material',
    desc: chapter[0] + ' — ' + chapter[1].substring(0, 80) + '...',
    cost: 0,
    isVoidFragment: true,
    fragmentNum: next,
    permanent: true
  };
  // Add to global inventory
  try { addToGlobalInventory(fragItem); } catch(e) {}

  // Check if complete
  if (next >= 25) {
    setTimeout(function() {
      awardAchievement('ach-void-child-complete');
      var completeMsg = '👁️ All 25 Void Fragments collected. The Void Chronicles are complete. The truth is in your library.';
      addLog(completeMsg);
      say(completeMsg);
    }, 2000);
  }
}

function addVoidChapterToLibrary(num, title, text) {
  try {
    var vChapters = _jsonParseSafe(DDStore.getItem('dd_void_chronicles'), '[]');
    // Check if already added
    if (vChapters.find(function(c){ return c.num === num; })) return;
    vChapters.push({ num: num, title: title, text: text, date: Date.now() });
    DDStore.setItem('dd_void_chronicles', JSON.stringify(vChapters));
  } catch(e) {}
}

function getVoidChronicles() {
  try { return _jsonParseSafe(DDStore.getItem('dd_void_chronicles'), '[]'); } catch(e) { return []; }
}

