      '<button type="button" onclick="dismissDungeonIntroStep1()" style="width:100%;padding:12px;background:#0a0a12;border:1px solid #446;color:#88aacc;font-family:Cinzel,serif;font-size:0.75rem;cursor:pointer;" aria-label="Got it, continue">Continue ↓</button>';
