var _hardcorePick = false;

function pickHardcoreMode(on) {
  _hardcorePick = on;
  var offBtn = document.getElementById('hardcore-off-btn');
  var onBtn  = document.getElementById('hardcore-on-btn');
  var warn   = document.getElementById('hardcore-warning');
  if (offBtn) {
    offBtn.setAttribute('aria-checked', String(!on));
    offBtn.style.borderColor = on ? '#333' : '#cc0000';
  }
  if (onBtn) {
    onBtn.setAttribute('aria-checked', String(on));
    onBtn.style.borderColor = on ? '#cc0000' : '#333';
  }
  if (warn) warn.style.display = on ? '' : 'none';
  NC.hardcore = on;
  if (on) {
    say('Warning. Hardcore Mode enabled. You have one life. If you die, your character is permanently deleted from save data. There is no retry, no continue, and no recovery. Select Standard above if you are not sure.');
  } else {
    say('Standard mode selected. Normal gameplay. Hardcore Mode disabled.');
  }
}

function handleHardcoreDeath() {
  // Delete character permanently
  if (DS.hardcoreMode && _charIdx !== null && CHARS[_charIdx]) {
    var name = CHARS[_charIdx].name || 'your character';
    // Build run summary BEFORE deleting the character so stats still show
    try { buildRunSummary(false); } catch(e) {}
    // Now delete
    CHARS.splice(_charIdx, 1);
    saveChars();
    _charIdx = null;
    // Hide the Play Again button on run summary since character is gone
    var btns = document.querySelector('#screen-runsummary .rs-btns');
    if (btns) {
      var playBtn = btns.querySelector('button');
      if (playBtn) playBtn.style.display = 'none';
    }
    // Go to run summary screen to show stats, then player can navigate away
    goTo('runsummary');
    var msg = '💀 HARDCORE — ' + name + ' has fallen. This character is gone forever. There are no second chances in Hardcore Mode.';
    say(msg);
    return true;
  }
  return false;
}
