// Show popup on page load
window.addEventListener('load', function() {
  loadFavorites();
  // Initialize IAP early so store is ready before player reaches coin shop
  setTimeout(function(){ initIAP(); }, 2000);

  // ── GLOBAL COMBAT BUTTON WATCHDOG ──
  // Runs every 1.5 seconds. If player is in active combat with buttons frozen, force-restores them.
  setInterval(function() {
    try {
      if (!DS || DS.hp <= 0) return;
      if (_selectingTarget) return;
      // BUGFIX: a cinematic/dialogue flag (e.g. the Medusa shield choice) that never gets
      // cleared — because its modal failed to show, or the player backgrounded the app at
      // the wrong moment — used to block this watchdog forever, leaving combat permanently
      // frozen with no recovery path. Treat a flag stuck for >20s as stale and proceed anyway.
      if (window._cinematicInProgress) {
        var _cinStale = window._cinematicStartedAt && (Date.now() - window._cinematicStartedAt) > 20000;
        if (!_cinStale) return;
        window._cinematicInProgress = false;
      }
      // If inCombat is true but enemy is null or dead — clean up stuck state
      if (DS.inCombat && (!DS.enemy || DS.enemy.hp <= 0)) {
        DS.inCombat = false;
        DS.enemy = null;
        setCombatBtns(true);
        // BUGFIX: previously this only re-enabled the attack button without leaving the
        // combat screen. Since doFight() now returns immediately once inCombat is false,
        // the enabled button did nothing — the player was stuck looking at a frozen/empty
        // combat screen with no way to proceed. Actually return to exploration instead.
        if (!_multiCombatActive) {
          try { showDgPanels(true, false, false); enterRoom(); } catch(eRecover) {}
        }
        return;
      }
      // Single combat check
      if (DS.inCombat && DS.enemy && DS.enemy.hp > 0) {
        // BUGFIX: a room-enter encounter roll (Chimera, The Shade, a Hollow
        // special encounter, etc.) sets DS.inCombat/DS.enemy and starts combat
        // audio well before it finishes building the fight — if anything in
        // between throws, the function aborts before ever calling
        // showDgPanels(false, true, false), so the room panel (#dg-nav) stays
        // visible with the combat panel hidden. DS.enemy is valid here, so the
        // stuck-state branch above never fires either — the player is left
        // looking at the room, unable to move (moveRoom short-circuits on
        // DS.inCombat) with no visible way to fight. Detect that mismatch
        // directly and force the combat panel to show.
        var navPanel = document.getElementById('dg-nav');
        var combatPanel = document.getElementById('dg-combat');
        if (navPanel && combatPanel && navPanel.style.display !== 'none' && combatPanel.style.display === 'none') {
          showDgPanels(false, true, false);
          // The crash that caused this could have landed before the enemy
          // icon/name were ever written too — restore them from DS.enemy
          // directly rather than trusting whatever's currently in the DOM.
          var eIcon = document.getElementById('dg-enemy-icon');
          var eName = document.getElementById('dg-enemy-name');
          if (eIcon && DS.enemy.icon) eIcon.textContent = DS.enemy.icon;
          if (eName && DS.enemy.name) eName.textContent = t(DS.enemy.name);
          updateEnemyBar(); updatePlayerBar();
          // Whatever threw mid-spawn may also have left the room-re-entry
          // guard stuck on — clear it so enterRoom() isn't refused again
          // once this fight actually ends.
          _roomResolving = false;
          say('Combat resumed.');
        }
        var atk = document.getElementById('cbtn-attack');
        if (atk && atk.disabled) { setCombatBtns(true); }
      }
      // Multi-combat check — clean up any dead enemies stuck in array
      if (_multiCombatActive) {
        var before = _multiEnemies.length;
        _multiEnemies = _multiEnemies.filter(function(e){ return e.hp > 0; });
        if (_multiEnemies.length === 0) { endMultiCombat(true, false); return; }
        if (_multiEnemies.length !== before) renderMultiEnemies();
        var atk2 = document.getElementById('cbtn-attack');
        if (atk2 && atk2.disabled) { setCombatBtns(true); }
      }
    } catch(e) {}
  }, 1500);
  // Apply saved language translation on load
  try {
    var _oldLang = DDStore.getItem('dd_language');
    if (_oldLang) {
      if (!DDStore.getItem('dd_lang')) DDStore.setItem('dd_lang', _oldLang);
      DDStore.removeItem('dd_language');
    }
    var _activeLang = DDStore.getItem('dd_lang') || 'en';
    if (_activeLang && _activeLang !== 'en') {
      setTimeout(function(){ applyFullUITranslation(_activeLang); }, 800);
    } else {
      document.documentElement.lang = 'en';
    }
  } catch(e) {}
});

