// HUNTER MODE
//═════════════════════════════

function pickHunterMode(on) {
  NC.hunterMode = on;
  var offBtn = document.getElementById('hunter-off-btn');
  var onBtn = document.getElementById('hunter-on-btn');
  if (offBtn) { offBtn.style.borderColor = on ? '#444' : '#cc4400'; offBtn.setAttribute('aria-checked', on ? 'false' : 'true'); }
  if (onBtn) { onBtn.style.borderColor = on ? '#cc4400' : '#444'; onBtn.setAttribute('aria-checked', on ? 'true' : 'false'); }
  say(on ? 'Hunter Mode ON. Something will hunt you through the dungeon. Every move you make, it moves too.' : 'Hunter Mode OFF. No hunter.');
}

function hunterTurn(isIdle) {
  if (!DS || !DS.hunterMode || !DS.hunterAlive) return;

  // Idle tracking
  if (isIdle) {
    DS.hunterIdleTurns = (DS.hunterIdleTurns || 0) + 1;
  } else {
    DS.hunterIdleTurns = 0;
  }

  // Speed: phase 1 = 1 step/turn, phase 2 = moves twice if idle, faster if player idles 3+
  var steps = 1;
  // Phase 2 announced it moves faster but still came one room a turn: an extra step every third turn
  DS._hunterTurns = (DS._hunterTurns || 0) + 1;
  if (DS.hunterPhase === 2 && DS._hunterTurns % 3 === 0) steps = 2;
  if (DS.hunterIdleTurns >= 3) steps = 2; // idle penalty — rushes

  DS.hunterDist = Math.max(0, (DS.hunterDist || 10) - steps);

  // Announce distance
  hunterAnnounce();

  // Caught!
  if ((DS.hunterDist !== null && DS.hunterDist !== undefined && DS.hunterDist <= 0) && !DS._hunterCaught) {
    hunterCatch();
  }
}

function hunterAnnounce() {
  if (!DS.hunterMode || !DS.hunterAlive) return;
  var dist = DS.hunterDist;
  var msg = '';

  if (dist >= 8) {
    msg = '🏹 The hunter is far behind. ' + dist + ' rooms away.';
  } else if (dist === 7) {
    msg = '🏹 You hear distant footsteps. The hunter is ' + dist + ' rooms away.';
  } else if (dist === 6) {
    msg = '🏹 The hunter draws closer. ' + dist + ' rooms away.';
  } else if (dist === 5) {
    msg = '🏹 You can hear breathing in the dark. ' + dist + ' rooms away.';
  } else if (dist === 4) {
    msg = '🏹 The hunter is close. ' + dist + ' rooms away. Keep moving.';
  } else if (dist === 3) {
    msg = '🏹 THREE rooms away. You need to move. NOW.';
  } else if (dist === 2) {
    msg = '🏹 TWO rooms. It can almost smell you. Fight or run.';
  } else if (dist === 1) {
    msg = '🏹 ONE room. It is right behind you. FIGHT OR RUN — NOW.';
  }

  if (msg) {
    addLog(msg);
    say(msg);
    updateHunterBar();
    updateHunterTracker();
    // Directional proximity pulse — a distinct one-shot on top of the
    // looping heartbeat below, panned to the direction the hunter is
    // actually coming from in 3D Mode.
    hunterProximitySound(dist);
    // Music switching based on distance
    if (dist <= 3) {
      playHunterMusic();
      if (dist === 3) companionOnHunterClose();
    }
    // Heartbeat — starts at 5 rooms, speeds up as hunter closes in
    if (dist <= 5) {
      var bpm = dist <= 1 ? 400 : dist <= 2 ? 600 : dist <= 3 ? 900 : 1200;
      startHeartbeatLoop(bpm);
    }
    // Show Fight/Run choice when hunter is 2 or 1 room away
    if (dist <= 2 && !DS.inCombat) {
      showHunterChoice();
    }
  }
}

function hunterProximitySound(dist) {
  vibe(VIBE.hunterClose);
  if (!AUD || !AUD.sfxOn) return;
  try {
    var ctx = new (window.AudioContext || window.webkitAudioContext)();
    var dirCue = _hunterDirCue();
    var dest = ctx.destination;
    if (dirCue && ctx.createStereoPanner) {
      var panner = ctx.createStereoPanner();
      panner.pan.value = dirCue.pan;
      panner.connect(ctx.destination);
      dest = panner;
    }
    var osc = ctx.createOscillator();
    var gain = ctx.createGain();
    osc.connect(gain);
    gain.connect(dest);
    // Lower pitch = further away, higher + faster = closer
    var freq = dist >= 6 ? 60 : dist >= 4 ? 80 : dist >= 2 ? 110 : 140;
    var vol = dist >= 6 ? 0.08 : dist >= 4 ? 0.15 : dist >= 2 ? 0.25 : 0.4;
    osc.type = 'sine';
    osc.frequency.setValueAtTime(freq, ctx.currentTime);
    gain.gain.setValueAtTime(0, ctx.currentTime);
    gain.gain.linearRampToValueAtTime(vol, ctx.currentTime + 0.05);
    gain.gain.linearRampToValueAtTime(0, ctx.currentTime + 0.3);
    osc.start(ctx.currentTime);
    osc.stop(ctx.currentTime + 0.35);
    // Double pulse when very close
    if (dist <= 2) {
      var osc2 = ctx.createOscillator();
      var gain2 = ctx.createGain();
      osc2.connect(gain2); gain2.connect(dest);
      osc2.type = 'sine';
      osc2.frequency.setValueAtTime(freq * 1.1, ctx.currentTime + 0.4);
      gain2.gain.setValueAtTime(0, ctx.currentTime + 0.4);
      gain2.gain.linearRampToValueAtTime(vol, ctx.currentTime + 0.45);
      gain2.gain.linearRampToValueAtTime(0, ctx.currentTime + 0.7);
      osc2.start(ctx.currentTime + 0.4);
      osc2.stop(ctx.currentTime + 0.75);
    }
  } catch(e) {}
}

function showHunterChoice() {
  if (document.getElementById('hunter-choice-overlay')) return;
  var ov = document.createElement('div');
  ov.id = 'hunter-choice-overlay';
  ov.setAttribute('role', 'dialog');
  ov.setAttribute('aria-modal', 'true');
  ov.setAttribute('aria-label', 'The hunter is almost here. Fight or run?');
  ov.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.92);z-index:8000;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:24px;';
  ov.innerHTML =
    '<div style="max-width:380px;width:100%;text-align:center;">' +
    '<div style="font-size:2rem;margin-bottom:12px;">🏹</div>' +
    '<div style="font-family:Cinzel,serif;font-size:1rem;color:#cc4444;margin-bottom:8px;letter-spacing:0.1em;">THE HUNTER IS HERE</div>' +
    '<div style="font-family:Cinzel,serif;font-size:0.68rem;color:#888;margin-bottom:24px;line-height:1.7;">Two rooms away. It has found you. You cannot outrun it forever.<br>Choose now.</div>' +
    '<div style="display:flex;flex-direction:column;gap:12px;">' +
    '<button onclick="hunterFight()" style="width:100%;padding:14px;background:#1a0000;border:2px solid #cc4444;color:#ff6644;font-family:Cinzel,serif;font-size:0.8rem;cursor:pointer;letter-spacing:0.1em;" aria-label="Fight the hunter">' +
    '⚔ FIGHT — Stand your ground. Face it.' +
    '</button>' +
    '<button onclick="hunterRun()" style="width:100%;padding:14px;background:#0a0800;border:1px solid #555;color:#888;font-family:Cinzel,serif;font-size:0.8rem;cursor:pointer;letter-spacing:0.1em;" aria-label="Run from the hunter">' +
    '🏃 RUN — Sprint away. Buy one more turn.' +
    '</button>' +
    '</div>' +
    '<div style="font-family:Cinzel,serif;font-size:0.6rem;color:#444;margin-top:16px;">Running resets distance to 1. It will catch you next time.</div>' +
    '</div>';
  document.body.appendChild(ov);
  setTimeout(function() {
    var first = ov.querySelector('button');
    if (first) first.focus();
  }, 100);
  say('The hunter is almost here. Choose: Fight the hunter, or Run and sprint away.');
}

function hunterFight() {
  var choiceOv = document.getElementById('hunter-choice-overlay');
  if (choiceOv) choiceOv.remove();

  // Build hunter as an enemy that scales with player level
  var lvl = DS.level || 1;
  var hunterEnemy = {
    name: 'The Hunter',
    icon: '🏹',
    hp: 60 + lvl * 20,
    maxHp: 60 + lvl * 20,
    atk: [8 + lvl * 3, 14 + lvl * 4],
    def: lvl * 2,
    xp: 100 + lvl * 30,
    gold: 50 + lvl * 15,
    isBoss: true,
    isHunter: true,
    desc: 'The one who hunts. Relentless. Unstoppable. Or so it thought.',
    loot: [{ name: "Hunter's Trophy", icon: '🏹', type: 'material', desc: 'Proof you stood your ground. Worth a fortune.', cost: 200 }]
  };

  DS.enemy = hunterEnemy;
  DS.inCombat = true;
  DS.hunterAlive = false; // Hunter is now in combat — stop advancing

  showDgPanels(false, true, false);
  setCombatBtns(true);
  var msg = '🏹 THE HUNTER attacks! HP: ' + hunterEnemy.hp + '. ATK: ' + hunterEnemy.atk[0] + '-' + hunterEnemy.atk[1] + '. This is the fight of your life.';
  setEvent('bad', msg);
  addLog(msg);
  say(msg);
  // Play battle music
  try { playTrack('battle'); } catch(e) {}
  updateHunterBar();
}

function hunterRun() {
  var choiceOv = document.getElementById('hunter-choice-overlay');
  if (choiceOv) choiceOv.remove();

  // Running costs hunter distance — it gets very close
  DS.hunterDist = 1;
  var msg = '🏃 You sprint away! The hunter is ONE room behind you. Do NOT stop moving.';
  addLog(msg);
  say(msg);
  updateHunterBar();
  showDgPanels(true, false, false);
  enterRoom();
}

function updateHunterTracker() {
  var tracker = document.getElementById('hunter-tracker');
  if (!tracker) return;
  if (!DS.hunterMode || !DS.hunterAlive) { tracker.style.display = 'none'; return; }
  tracker.style.display = 'block';
  var dist = DS.hunterDist || 10;
  var maxDist = 12;
  var pct = Math.max(0, Math.min(100, (dist / maxDist) * 100));
  var fill = document.getElementById('hunter-track-fill');
  var label2 = document.getElementById('hunter-dist-label');
  var hunterIcon = document.getElementById('hunter-enemy-icon');
  var color = dist >= 6 ? '#2a6a2a' : dist >= 4 ? '#aa8800' : dist >= 2 ? '#cc4400' : '#cc0000';
  if (fill) { fill.style.width = pct + '%'; fill.style.background = color; }
  if (label2) {
    label2.textContent = dist <= 1 ? 'RIGHT BEHIND YOU' :
                         dist <= 2 ? dist + ' rooms — FIGHT OR RUN' :
                         dist <= 3 ? dist + ' rooms — CLOSE' :
                         dist + ' rooms away';
  }
  if (hunterIcon) {
    if (dist <= 2) hunterIcon.classList.add('close');
    else hunterIcon.classList.remove('close');
  }
  var playerIcon = document.getElementById('hunter-player-icon');
  if (playerIcon && DS.cls) {
    var icons = {warrior:'⚔️',mage:'🔮',rogue:'🗡️',cleric:'✝️',ranger:'🏹',
                 sentinel:'🛡️',necromancer:'💀',bard:'🎵',monk:'👊',druid:'🌿',
                 assassin:'🗡️',paladin:'⚔️',bloodknight:'🩸',warlock:'👁️',
                 alchemist:'⚗️',sorcerer:'✨',wizard:'🧙',deathknight:'💀'};
    playerIcon.textContent = icons[DS.cls] || '⚔️';
  }
}

// ── LIVE STATUS (Android notification / iOS Live Activity) ──
// A persistent, glanceable status (Hunter distance, Endless Descent
// progress) while the game runs or is briefly backgrounded. Android uses
// a plain ongoing notification (GameStatusNotification); iOS uses a real
// Live Activity (LiveActivity, requires iOS 16.2+ — the plugin itself
// silently no-ops below that). Both guarded by plugin existence, so this
// is a clean no-op on web.
var _liveActivityStarted = false;
function _gameStatusNotify(title, text) {
  try {
    if (window.Capacitor && Capacitor.Plugins && Capacitor.Plugins.GameStatusNotification) {
      Capacitor.Plugins.GameStatusNotification.show({ title: title, text: text }).catch(function(){});
    }
  } catch(e) {}
  try {
    if (window.Capacitor && Capacitor.Plugins && Capacitor.Plugins.LiveActivity) {
      if (_liveActivityStarted) {
        Capacitor.Plugins.LiveActivity.update({ title: title, text: text }).catch(function(){});
      } else {
        Capacitor.Plugins.LiveActivity.start({ title: title, text: text }).then(function(){ _liveActivityStarted = true; }).catch(function(){});
      }
    }
  } catch(e) {}
}
function _gameStatusHide() {
  try {
    if (window.Capacitor && Capacitor.Plugins && Capacitor.Plugins.GameStatusNotification) {
      Capacitor.Plugins.GameStatusNotification.hide().catch(function(){});
    }
  } catch(e) {}
  try {
    if (window.Capacitor && Capacitor.Plugins && Capacitor.Plugins.LiveActivity && _liveActivityStarted) {
      Capacitor.Plugins.LiveActivity.end().then(function(){ _liveActivityStarted = false; }).catch(function(){});
    }
  } catch(e) {}
}

function updateHunterBar() {
  updateHunterTracker();
  var bar = document.getElementById('dg-hunter-bar');
  var label = document.getElementById('dg-hunter-label');
  if (!bar || !label) return;
  if (!DS.hunterMode || !DS.hunterAlive) {
    bar.parentElement.style.display = 'none';
    _gameStatusHide();
    return;
  }
  bar.parentElement.style.display = '';
  var pct = Math.round((DS.hunterDist / 10) * 100);
  bar.style.width = pct + '%';
  // Color shifts red as hunter closes in
  var color = DS.hunterDist >= 6 ? '#cc4400' : DS.hunterDist >= 3 ? '#ff6600' : '#ff0000';
  bar.style.background = color;
  var hunterText = '🏹 Hunter: ' + DS.hunterDist + ' room' + (DS.hunterDist === 1 ? '' : 's') + ' away';
  label.textContent = hunterText;
  label.style.color = color;
  _gameStatusNotify('Dungeon Descent', hunterText);
}

function hunterCatch() {
  // Guard — hunterCatch can only fire once per run
  if (DS._hunterCaught) return;
  DS._hunterCaught = true;
  DS.hunterAlive = false;
  DS.inCombat = false;
  stopHeartbeatLoop();
  stopHunterMusic();
  vibe(VIBE.hunterCatch);
  hunterJumpScare();
  playHunterJumpScare();
  sfx('sfx-death');
  var msg = '🏹 The hunter reaches you. There is nowhere left to run. You have been defeated.';
  addLog(msg);
  say(msg);
  updateHunterBar();
  // Lose a life — but don't decrement here if handleDeath will also decrement
  // Instead call showDefeat directly if out of lives, or handleDeath for the respawn flow
  setTimeout(function() {
    if ((DS.lives || 1) <= 1) {
      // Out of lives — go straight to defeat
      DS.lives = 0;
      DS.inCombat = false;
      say('Defeated. The hunter claims you. All lives lost.');
      setTimeout(function() { showDefeat(); }, 800);
    } else {
      // Has lives remaining — lose one and respawn
      DS.lives = Math.max(0, (DS.lives || 1) - 1);
      DS.hunterDist = 8;
      DS.hunterAlive = true;
      DS.hunterIdleTurns = 0;
      var respawnMsg = '🏹 The hunter circles back. It is 8 rooms away. Do not waste this chance. Lives remaining: ' + DS.lives + '.';
      addLog(respawnMsg);
      say(respawnMsg);
      updateHunterBar();
      showDgPanels(true, false, false);
      enterRoom();
    }
  }, 1500);
}

function hunterPhaseUp() {
  if (!DS.hunterMode || !DS.hunterAlive) return;
  DS.hunterPhase = 2;
  var msg = '🏹 The hunter has found your trail. It is moving faster now.';
  addLog(msg);
  say(msg);
  updateHunterBar();
}

function toggleGuideFromPause() {
  DS.guideEnabled = !DS.guideEnabled;
  var status = document.getElementById('pause-guide-status');
  if (status) status.textContent = DS.guideEnabled ? 'ON' : 'OFF';
  // Hide companion bubble if turning off
  if (!DS.guideEnabled) dismissCompanion();
  say('Guide ' + (DS.guideEnabled ? 'enabled. Your companion will speak again.' : 'disabled. Your companion is silent.'));
}

function toggleHunterMode() {
  if (!DS) return;
  DS.hunterMode = !DS.hunterMode;
  if (DS.hunterMode) {
    DS.hunterDist = 10;
    DS.hunterPhase = 1;
    DS.hunterIdleTurns = 0;
    DS.hunterAlive = true;
    var on = '🏹 Hunter Mode enabled. Something stirs in the dark. It is 10 rooms behind you.';
    addLog(on); say(on);
  } else {
    DS.hunterAlive = false;
    stopHeartbeatLoop();
    stopHunterMusic();
    updateHunterTracker();
    var off = '🏹 Hunter Mode disabled. The dungeon is silent again.';
    addLog(off); say(off);
  }
  updateHunterBar();
  // Save to character
  try {
    var chars = _jsonParseSafe(DDStore.getItem('dd_chars'), '[]');
    if (chars[_charIdx]) { chars[_charIdx].hunterMode = DS.hunterMode; DDStore.setItem('dd_chars', JSON.stringify(chars)); }
  } catch(e) {}
}

function hunterSlain() {
  DS.hunterMode = false;
  DS.hunterAlive = false;
  DS.inCombat = false;
  stopHeartbeatLoop();
  stopHunterMusic();
  vibe(VIBE.hunterKill);
  updateHunterTracker();
  // Hide hunter bar
  var hunterRow = document.getElementById('dg-hunter-row');
  if (hunterRow) hunterRow.style.display = 'none';
  sfx('sfx-victory');
  var msg = '🏹 THE HUNTER IS DEAD. You stood your ground and won. The dungeon is yours. Hunter Mode deactivated.';
  setEvent('good', msg);
  addLog(msg);
  say(msg);
  // Drop Hunter's Trophy into inventory
  DS.inventory.push({ name:"Hunter's Trophy", icon:'🏹', type:'material', desc:'You killed the hunter. Proof that you are something the dungeon fears.', cost:200 });
  // Give XP and gold
  DS.xp += 200 + (DS.level || 1) * 30;
  DS.gold += 100 + (DS.level || 1) * 15;
  updateTopBar();
  setTimeout(function() {
    showDgPanels(true, false, false);
    enterRoom();
  }, 1500);
}

function hunterJumpScare() {
  // Flash screen red + scare sound
  var flash = document.createElement('div');
  flash.style.cssText = 'position:fixed;inset:0;background:#cc0000;z-index:99999;opacity:0.9;pointer-events:none;animation:hunterScare 0.6s ease forwards;';
  flash.setAttribute('aria-hidden', 'true');
  document.body.appendChild(flash);
  setTimeout(function() { if (flash.parentNode) flash.parentNode.removeChild(flash); }, 700);
  // Scare sound via Web Audio
  try {
    var ctx = new (window.AudioContext || window.webkitAudioContext)();
    var osc = ctx.createOscillator();
    var gain = ctx.createGain();
    osc.connect(gain); gain.connect(ctx.destination);
    osc.type = 'sawtooth';
    osc.frequency.setValueAtTime(200, ctx.currentTime);
    osc.frequency.linearRampToValueAtTime(40, ctx.currentTime + 0.5);
    gain.gain.setValueAtTime(0.5, ctx.currentTime);
    gain.gain.linearRampToValueAtTime(0, ctx.currentTime + 0.6);
    osc.start(ctx.currentTime);
    osc.stop(ctx.currentTime + 0.65);
  } catch(e) {}
}

