// SHADOW REALM — SECRET WAVE SURVIVAL MODE
// Accessed via: Settings → Redeem Code → SHADOW
// --═

var SR = {
  active: false,
  charIdx: 0,
  charName: '',
  cls: '',
  wave: 1,
  kills: 0,
  hp: 100,
  maxHp: 100,
  atk: 10,
  def: 0,
  potions: 3,
  defending: false,
  enemy: null,
  inCombat: false
};

// ── Shadow enemy pool — scales with wave ──
function getShadowEnemies(wave) {
  var tier = Math.floor((wave - 1) / 5); // tier up every 5 waves
  var base = [
    { name:'Shadow Wisp',      icon:'🌑', hp: 30 + tier*12,  atk:[4+tier*2, 8+tier*3],  gold:0, desc:'A flicker of dark energy.' },
    { name:'Void Stalker',     icon:'👤', hp: 45 + tier*15,  atk:[5+tier*2, 10+tier*3], gold:0, desc:'It moves without sound.' },
    { name:'Shade Wraith',     icon:'👻', hp: 60 + tier*18,  atk:[6+tier*3, 12+tier*4], gold:0, desc:'Passes through walls. Not through you.' },
    { name:'Dark Sentinel',    icon:'🗿', hp: 80 + tier*20,  atk:[7+tier*3, 14+tier*4], gold:0, desc:'Ancient. Patient. Violent.' },
    { name:'Nightmare Hound',  icon:'🐺', hp: 55 + tier*16,  atk:[8+tier*3, 15+tier*4], gold:0, desc:'Runs on shadow and hunger.' },
    { name:'Corruption Core',  icon:'💜', hp: 100 + tier*25, atk:[9+tier*4, 17+tier*5], gold:0, desc:'A collapsed star of pure shadow.' },
  ];
  // Boss every 10 waves
  if (wave % 10 === 0) {
    return {
      name: 'Shadow Sovereign',
      icon: '👑',
      hp: 200 + wave * 8,
      atk: [12 + wave, 20 + wave],
      gold: 0,
      isBoss: true,
      desc: 'The ruler of this place. It knows you are here.'
    };
  }
  return base[Math.floor(Math.random() * base.length)];
}

// ── Open intro screen ──
function openShadowRealmIntro() {
  goTo('shadow-intro');
  say('The Shadow Realm. You were not supposed to find this. A secret mode — endless waves of shadow entities. How long can you survive? Press Enter the Shadow to continue.');
}

// ── Open character select ──
function openShadowRealmCharSelect() {
  SR.charIdx = 0;
  goTo('shadow-charselect');
  shadowRenderCharDisplay();
  say('Shadow Realm. Choose your champion. Use left and right arrows to browse your characters, then press Begin.');
}

// ── Character slider for Shadow Realm ──
function shadowCharStep(dir) {
  if (!CHARS || CHARS.length === 0) return;
  SR.charIdx = (SR.charIdx + dir + CHARS.length) % CHARS.length;
  shadowRenderCharDisplay();
}

function shadowRenderCharDisplay() {
  var display = document.getElementById('shadow-char-display');
  var msg = document.getElementById('shadow-charselect-msg');
  if (!display) return;
  if (!CHARS || CHARS.length === 0) {
    display.innerHTML = '<div style="color:#555;font-family:Cinzel,serif;font-size:0.75rem;">No characters found.<br>Create one first.</div>';
    if (msg) msg.textContent = 'You need at least one character.';
    return;
  }
  var ch = CHARS[SR.charIdx];
  if (!ch || !ch.name) {
    display.innerHTML = '<div style="color:#555;font-size:0.75rem;">Empty slot</div>';
    return;
  }
  var lvl = ch.persistLevel || ch.level || 1;
  display.innerHTML =
    "<div style=\"font-family:'Cinzel Decorative',cursive;font-size:0.9rem;color:#bb66ff;margin-bottom:4px;\">" + ch.name + "</div>" +
    "<div style=\"font-family:Cinzel,serif;font-size:0.7rem;color:#888;\">Lv" + lvl + " " + (ch.race||"") + " " + (ch.cls||"") + "</div>" +
    "<div style=\"font-family:Cinzel,serif;font-size:0.65rem;color:#555;margin-top:2px;\">" + (SR.charIdx+1) + " / " + CHARS.length + "</div>";
  display.setAttribute('aria-label', ch.name + ', level ' + lvl + ' ' + (ch.race||'') + ' ' + (ch.cls||'') + '. Character ' + (SR.charIdx+1) + ' of ' + CHARS.length);
  if (msg) msg.textContent = '';
}

// ── Start Shadow Realm ──
function startShadowRealm() {
  var ch = CHARS[SR.charIdx];
  if (!ch || !ch.name) {
    var msg = document.getElementById('shadow-charselect-msg');
    if (msg) msg.textContent = 'Select a character first.';
    say('Select a character first.'); return;
  }

  var lvl = ch.persistLevel || ch.level || 1;
  SR.active = true;
  SR.charName = ch.name;
  SR.cls = ch.cls || 'Adventurer';
  SR.wave = 1;
  SR.kills = 0;
  SR.maxHp = (HP_MAP[ch.cls] || 100) + (lvl - 1) * 15;
  SR.hp = SR.maxHp;
  SR.atk = 10 + (ch.atkBonus || 0) + (lvl - 1) * 2;
  SR.def = ch.defBonus || 0;
  SR.potions = 3;
  SR.defending = false;
  SR.inCombat = false;

  // Apply global equipped weapon
  try {
    var sw = _jsonParseSafe(DDStore.getItem('dd_equipped_weapon'), 'null');
    if (sw && sw.atkBase) {
      var atkArr = getWeaponAtk(sw);
      SR.atk += Math.floor((atkArr[0] + atkArr[1]) / 2);
    }
    var sa = _jsonParseSafe(DDStore.getItem('dd_equipped_armor'), 'null');
    if (sa) SR.def += sa.defBase || sa.defBonus || 0;
  } catch(e) {}

  goTo('shadow-combat');
  shadowRenderUI();
  shadowSpawnEnemy();
  try { playTrack('void-reaper'); } catch(e) {}
  say('Entering the Shadow Realm. ' + SR.charName + '. Wave 1. HP: ' + SR.hp + '. The shadows stir.');
}

// ── Render UI ──
function shadowRenderUI() {
  var hpPct = Math.max(0, Math.round(SR.hp / SR.maxHp * 100));
  document.getElementById('shadow-hp-bar').style.width = hpPct + '%';
  document.getElementById('shadow-hp-label').textContent = 'HP: ' + SR.hp + ' / ' + SR.maxHp;
  document.getElementById('shadow-wave-display').textContent = 'Wave ' + SR.wave;
  document.getElementById('shadow-kills-display').textContent = 'Kills: ' + SR.kills;
  document.getElementById('shadow-char-name').textContent = SR.charName + ' the ' + SR.cls;
  document.getElementById('shadow-potion-count').textContent = SR.potions;
}

function shadowLog(msg) {
  var log = document.getElementById('shadow-log');
  if (!log) return;
  var line = document.createElement('div');
  line.textContent = msg;
  log.appendChild(line);
  log.scrollTop = log.scrollHeight;
}

function shadowStatus(msg) {
  var el = document.getElementById('shadow-status');
  if (el) el.textContent = msg;
}

// ── Spawn enemy ──
function shadowSpawnEnemy() {
  SR.enemy = getShadowEnemies(SR.wave);
  SR.enemy.maxHp = SR.enemy.hp;
  SR.defending = false;
  SR.inCombat = true;

  document.getElementById('shadow-enemy-name').textContent = SR.enemy.icon + ' ' + SR.enemy.name + (SR.enemy.isBoss ? ' 👑' : '');
  document.getElementById('shadow-enemy-hp').textContent = 'HP: ' + SR.enemy.hp + ' / ' + SR.enemy.maxHp;
  document.getElementById('shadow-enemy-bar').style.width = '100%';
  document.getElementById('shadow-next-wrap').style.display = 'none';
  document.getElementById('shadow-action-btns').style.display = 'grid';

  var msg = (SR.enemy.isBoss ? '👑 BOSS — ' : '') + SR.enemy.name + ' emerges from the shadow. Wave ' + SR.wave + '.';
  shadowStatus(msg);
  shadowLog(msg);
  say(msg + ' HP: ' + SR.enemy.hp + '. Attack: ' + SR.enemy.atk[0] + ' to ' + SR.enemy.atk[1] + '.');
}

// ── Attack ──
function shadowAttack(type) {
  if (!SR.inCombat || !SR.enemy || SR.enemy.hp <= 0) return;
  SR.defending = false;

  var playerAtk, hit = true;
  if (type === 'attack') {
    playerAtk = SR.atk + Math.floor(Math.random() * 6);
  } else if (type === 'heavy') {
    if (Math.random() < 0.25) { hit = false; }
    playerAtk = Math.round((SR.atk + Math.floor(Math.random() * 8)) * 1.6);
  } else if (type === 'defend') {
    SR.defending = true;
    playerAtk = Math.floor((SR.atk + Math.floor(Math.random() * 4)) * 0.5);
    shadowLog('🛡 You brace yourself, striking back for ' + playerAtk + ' damage.');
    say('Defending. You strike for ' + playerAtk + '.');
  }

  if (!hit) {
    shadowLog('💨 Heavy strike misses — the shadow steps aside.');
    say('Heavy strike missed.'); 
  } else if (type !== 'defend') {
    SR.enemy.hp -= playerAtk;
    shadowLog('⚔ You hit ' + SR.enemy.name + ' for ' + playerAtk + ' damage.');
    say('You hit for ' + playerAtk + '.');
  } else {
    SR.enemy.hp -= playerAtk;
  }

  SR.enemy.hp = Math.max(0, SR.enemy.hp);
  var enemyHpPct = Math.round(SR.enemy.hp / SR.enemy.maxHp * 100);
  document.getElementById('shadow-enemy-bar').style.width = enemyHpPct + '%';
  document.getElementById('shadow-enemy-hp').textContent = 'HP: ' + SR.enemy.hp + ' / ' + SR.enemy.maxHp;

  if (SR.enemy.hp <= 0) {
    shadowEnemyDied();
    return;
  }

  // Enemy attacks back
  setTimeout(function() { shadowEnemyAttack(); }, 400);
}

// ── Enemy attacks player ──
function shadowEnemyAttack() {
  if (!SR.enemy || SR.enemy.hp <= 0) return;
  var rawAtk = SR.enemy.atk[0] + Math.floor(Math.random() * (SR.enemy.atk[1] - SR.enemy.atk[0] + 1));
  var dmg = Math.max(1, rawAtk - SR.def - (SR.defending ? Math.floor(SR.atk * 0.3) : 0));
  SR.hp -= dmg;
  SR.hp = Math.max(0, SR.hp);

  var logMsg = SR.enemy.icon + ' ' + SR.enemy.name + ' hits you for ' + dmg + ' damage.';
  if (SR.defending) logMsg += ' (Blocked some!)';
  shadowLog(logMsg);
  shadowStatus('HP: ' + SR.hp + ' / ' + SR.maxHp);
  say(logMsg);
  shadowRenderUI();

  if (SR.hp <= 0) {
    setTimeout(function() { shadowDie(); }, 400);
  }
}

// ── Enemy died ──
function shadowEnemyDied() {
  SR.kills++;
  SR.inCombat = false;
  var msg = SR.enemy.name + ' is consumed by its own shadow. Wave ' + SR.wave + ' cleared!';
  shadowLog('💀 ' + msg);
  shadowStatus(msg);
  say(msg);
  shadowRenderUI();

  // Restore a bit of HP between waves (5% of max, min 5)
  var heal = Math.max(5, Math.floor(SR.maxHp * 0.05));
  SR.hp = Math.min(SR.maxHp, SR.hp + heal);
  if (heal > 0) shadowLog('✨ The silence heals you slightly. +' + heal + ' HP.');

  document.getElementById('shadow-action-btns').style.display = 'none';
  document.getElementById('shadow-next-wrap').style.display = 'block';
  shadowRenderUI();
}

// ── Next wave ──
function shadowNextWave() {
  vibe(VIBE.shadowWave);
  SR.wave++;
  shadowRenderUI();
  document.getElementById('shadow-log').innerHTML = '';
  shadowSpawnEnemy();
}

// ── Use potion ──
function shadowUsePotion() {
  if (SR.potions <= 0) { say('No potions left.'); return; }
  SR.potions--;
  var heal = Math.floor(SR.maxHp * 0.40);
  SR.hp = Math.min(SR.maxHp, SR.hp + heal);
  shadowLog('🧪 You drink a potion. +' + heal + ' HP.');
  say('Potion used. Restored ' + heal + ' HP. ' + SR.potions + ' remaining.');
  shadowRenderUI();
}

// ── Player died ──
function shadowDie() {
  SR.active = false;
  SR.inCombat = false;

  // Save to leaderboard
  var board = _jsonParseSafe(DDStore.getItem('dd_shadow_leaderboard'), '[]');
  board.push({
    name: SR.charName,
    cls: SR.cls,
    wave: SR.wave,
    kills: SR.kills,
    date: new Date().toLocaleDateString()
  });
  // Sort by wave descending, keep top 10
  board.sort(function(a,b){ return b.wave - a.wave || b.kills - a.kills; });
  board = board.slice(0, 10);
  DDStore.setItem('dd_shadow_leaderboard', JSON.stringify(board));

  goTo('shadow-death');
  document.getElementById('shadow-death-wave').textContent = 'Fell on Wave ' + SR.wave;
  document.getElementById('shadow-death-kills').textContent = SR.kills + ' shadow entit' + (SR.kills === 1 ? 'y' : 'ies') + ' destroyed.';

  // Render leaderboard
  var lb = document.getElementById('shadow-leaderboard');
  if (lb) {
    if (board.length === 0) {
      lb.innerHTML = '<div style="color:#444;text-align:center;">No records yet.</div>';
    } else {
      lb.innerHTML = board.map(function(entry, i) {
        var medal = i === 0 ? '🥇' : i === 1 ? '🥈' : i === 2 ? '🥉' : (i+1) + '.';
        var isThisRun = (entry.name === SR.charName && entry.wave === SR.wave && entry.kills === SR.kills);
        var color = isThisRun ? '#bb66ff' : (i === 0 ? '#ffd700' : '#888');
        return '<div role="listitem" style="color:' + color + ';display:flex;justify-content:space-between;" aria-label="' + (i+1) + '. ' + entry.name + ', wave ' + entry.wave + ', ' + entry.kills + ' kills">' +
          '<span>' + medal + ' ' + entry.name + ' (' + entry.cls + ')</span>' +
          '<span>Wave ' + entry.wave + ' · ' + entry.kills + 'kills</span>' +
        '</div>';
      }).join('');
    }
  }

  say('You have been consumed by the shadow. Wave ' + SR.wave + '. ' + SR.kills + ' enemies destroyed. Leaderboard updated.');
}

// ── Open inventory from Shadow Realm ──
function openShadowInventory() {
  // Sync global keepable items first
  try {
    var _kt = ['soul-trap','enchanter','music-player','skill-orb'];
    var _gi = getGlobalInventory();
    if (!DS.inventory) DS.inventory = [];
    _gi.filter(function(i){ return _kt.indexOf(i.type) !== -1; }).forEach(function(ki) {
      var already = DS.inventory.some(function(di){ return di.type === ki.type && di.id === ki.id; });
      if (!already) DS.inventory.push(ki);
    });
  } catch(e) {}
  // BUGFIX: this referenced #ov-inv, which doesn't exist anywhere in the
  // page — the real inventory panel is #dg-inv, toggled via display (see
  // toggleInv()), not a class="overlay" element with an .open class. The
  // Inventory button in Shadow Realm silently did nothing.
  var panel = document.getElementById('dg-inv');
  if (panel) {
    renderInv();
    panel.style.display = '';
    say('Inventory opened. ' + (DS.inventory ? DS.inventory.length : 0) + ' items. Armor equipping is locked during combat.');
  }
}

// ── Retreat (voluntary exit) ──
function shadowRetreat() {
  if (SR.inCombat) {
    // Count as a death
    shadowDie();
  } else {
    SR.active = false;
    goTo('menu');
    say('You retreat from the Shadow Realm.');
  }
}


//═════════════════
// RHYTHM MINI GAME — ABYSSAL DEEP PHASE 4
//═════════════════
var _rhythmBeats = [];
var _rhythmTaps = [];
var _rhythmActive = false;
var _rhythmPhase = 'waiting';
var _rhythmBeatInterval = 800;
var _rhythmWindow = 420;

function triggerRhythmGame() {
  if (_rhythmActive) return;
  _rhythmActive = true;
  _rhythmTaps = [];
  _rhythmBeats = [];
  _rhythmPhase = 'waiting';
  setCombatBtns(false);
  stopAmbient();
  try { if(AUD.current && AUD.tracks[AUD.current]) AUD.tracks[AUD.current].pause(); } catch(e){}
  var ov = document.getElementById('rhythm-game-overlay');
  if (ov) { ov.style.display = 'flex'; setTimeout(function(){ ov.focus(); }, 100); }
  [1,2,3].forEach(function(i){ var p = document.getElementById('rhythm-pip-'+i); if(p){ p.style.background='#111'; p.style.borderColor='#334'; } });
  var st = document.getElementById('rhythm-status');
  if (st) st.textContent = 'Listen to the beats...';
  say('The abyss speaks. Listen to the three beats. Then tap the button three times to match the same rhythm.');
  setTimeout(function(){ playRhythmBeats(); }, 2200);
}

function playRhythmBeats() {
  _rhythmPhase = 'playing';
  var beat = 0;
  var ctx = null;
  try { ctx = new (window.AudioContext || window.webkitAudioContext)(); } catch(e){}

  function playBeep() {
    if (!ctx) return;
    try {
      var osc = ctx.createOscillator();
      var gain = ctx.createGain();
      osc.connect(gain); gain.connect(ctx.destination);
      osc.frequency.value = 160;
      gain.gain.setValueAtTime(0.5, ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.2);
      osc.start(ctx.currentTime); osc.stop(ctx.currentTime + 0.2);
    } catch(e){}
  }

  function doBeat() {
    _rhythmBeats.push(Date.now());
    playBeep();
    var pip = document.getElementById('rhythm-pip-' + (beat + 1));
    if (pip) { pip.style.background='#4488ff'; pip.style.borderColor='#88aaff'; setTimeout(function(){ pip.style.background='#111'; pip.style.borderColor='#334'; }, 200); }
    beat++;
    if (beat < 3) {
      setTimeout(doBeat, _rhythmBeatInterval);
    } else {
      setTimeout(startRhythmTapping, _rhythmBeatInterval + 400);
    }
  }
  doBeat();
}

function startRhythmTapping() {
  _rhythmPhase = 'tapping';
  _rhythmTaps = [];
  [1,2,3].forEach(function(i){ var p = document.getElementById('rhythm-pip-'+i); if(p){ p.style.background='#111'; p.style.borderColor='#334'; } });
  var st = document.getElementById('rhythm-status');
  if (st) st.textContent = 'Now tap — match the rhythm!';
  say('Now tap the button three times matching the same rhythm.');
  DS._rhythmTimeout = setTimeout(function(){
    if (_rhythmPhase === 'tapping') rhythmResult(false);
  }, 5000);
}

function rhythmTap() {
  if (_rhythmPhase !== 'tapping') return;
  var now = Date.now();
  _rhythmTaps.push(now);
  var idx = _rhythmTaps.length;
  var pip = document.getElementById('rhythm-pip-' + idx);
  if (pip) { pip.style.background='#44cc44'; pip.style.borderColor='#88ff88'; }
  if (_rhythmTaps.length === 3) {
    clearTimeout(DS._rhythmTimeout);
    setTimeout(evaluateRhythm, 300);
  }
}

function evaluateRhythm() {
  var bi1 = _rhythmBeats[1] - _rhythmBeats[0];
  var bi2 = _rhythmBeats[2] - _rhythmBeats[1];
  var ti1 = _rhythmTaps[1]  - _rhythmTaps[0];
  var ti2 = _rhythmTaps[2]  - _rhythmTaps[1];
  var win = Math.abs(ti1 - bi1) <= _rhythmWindow && Math.abs(ti2 - bi2) <= _rhythmWindow;
  rhythmResult(win);
}

function rhythmResult(win) {
  _rhythmPhase = 'done';
  _rhythmActive = false;
  var ov = document.getElementById('rhythm-game-overlay');
  var st = document.getElementById('rhythm-status');
  if (win) {
    if (st) st.textContent = '✓ You answered. The abyss is not done with you yet.';
    say('You answered the call. Power surges through you. Plus 40 percent attack and plus 30 percent defense for 2 turns.');
    [1,2,3].forEach(function(i){ var p=document.getElementById('rhythm-pip-'+i); if(p){p.style.background='#ccaa00';p.style.borderColor='#ffdd44';} });
    setTimeout(function(){
      if (ov) ov.style.display = 'none';
      // (the bonus was saved and never read — and DS.atk is a range, so it was NaN)
      var _rf = fxGet();
      if (_rf.buffTurns > 0) { DS.atkBonus -= _rf.buffAtk; DS.defBonus -= _rf.buffDef; }
      _rf.buffAtk = Math.round(((DS.atk[0] + DS.atk[1]) / 2 + (DS.atkBonus || 0)) * 0.4);
      _rf.buffDef = Math.max(1, Math.round(((DS.def || 0) + (DS.defBonus || 0)) * 0.3));
      _rf.buffTurns = 2;
      DS.atkBonus += _rf.buffAtk; DS.defBonus += _rf.buffDef;
      addLog('🌊 You answered the call! +40% ATK and +30% DEF for 2 turns.');
      updateAchievementStat('rhythmWon', 1);
      awardAchievement('ach-rhythm-win');
      playTrack(battleTrack());
      setCombatBtns(true);
      updatePlayerBar();
    }, 2000);
  } else {
    if (st) st.textContent = '✗ You hesitated. The abyss does not forgive.';
    say('You hesitated. The abyss does not forgive. The Leviathan enrages. Its attacks grow 30 percent stronger.');
    [1,2,3].forEach(function(i){ var p=document.getElementById('rhythm-pip-'+i); if(p){p.style.background='#cc0000';p.style.borderColor='#ff4444';} });
    setTimeout(function(){
      if (ov) ov.style.display = 'none';
      if (DS.enemy) { DS.enemy.atk = DS.enemy.atk.map(function(v){ return Math.round(v*1.3); }); }
      addLog('💀 You failed the call. The Leviathan enrages — its attacks are now 30% stronger!');
      playTrack(battleTrack());
      setCombatBtns(true);
    }, 2000);
  }
}





